DO $$ BEGIN IF EXISTS (SELECT 1 FROM agent_task_queue WHERE workflow_action_id IS NOT NULL OR workflow_operation_id IS NOT NULL OR workflow_branch_key IS NOT NULL) THEN RAISE EXCEPTION 'agent tasks contain durable workflow action bindings'; END IF; ALTER TABLE agent_task_queue DROP COLUMN IF EXISTS workflow_branch_key, DROP COLUMN IF EXISTS workflow_operation_id, DROP COLUMN IF EXISTS workflow_action_id; END $$;
